const items = $input.all();
const output = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const jobs = body.jobs || [];

  for (const job of jobs) {
    const title = (job.title || '').toLowerCase();
    const location = (job.location || '').toLowerCase();
    const isRemote = job.isRemote === true || location.includes('remote') || location.includes('us');
    const isTargetRole = title.includes('systems') || title.includes('infrastructure') || title.includes('distributed') || title.includes('senior') || title.includes('staff');

    if (isRemote && isTargetRole) {
      let score = 82;
      if (title.includes('staff') || title.includes('lead')) score += 10;
      if (title.includes('distributed') || title.includes('infrastructure')) score += 6;

      output.push({
        json: {
          id: 'ashby-' + (job.id || Math.random().toString(36).substring(2, 9)),
          company: 'Modal Labs',
          title: job.title,
          location: job.location || 'Remote (US)',
          board_type: 'ashby',
          external_url: job.jobUrl || 'https://modal.com/careers',
          match_score: Math.min(score, 98),
          published_at: job.publishedAt
        }
      });
    }
  }
}

return output;
